"use client";

import { Liveline, type LivelinePoint, type LivelineSeries } from "liveline";
import { useEffect, useMemo, useState } from "react";

/* ─────────────────────────────────────────────────────────
 * INSIGHT CARDS
 * Embedded mini-visualizations in an "Insights N ‹ ›"
 * carousel. Autoplay yields as soon as a person uses it.
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16, 1, 0.3, 1)";

const formatPercent = (v: number) => `${v > 0 ? "+" : ""}${v.toFixed(2)}%`;
const formatMoney = (v: number) => `$${Math.round(v).toLocaleString("en-US")}`;
/* anchor the snapshot to *call* time (inside each card's mount-time memo) —
 * a module-load constant goes stale, and once the points age past the chart
 * window the canvas renders empty */
function makePoints(values: number[], gap = 6): LivelinePoint[] {
  const end = Math.floor(Date.now() / 1000);
  return values.map((value, index) => ({
    time: end - (values.length - 1 - index) * gap,
    value,
  }));
}

/* Catmull-Rom resample — turn a sparse series into a dense, smoothly curved
 * one so both the line and the hover cursor glide instead of stepping between
 * a handful of points. */
function smooth(values: number[], perSegment = 9): number[] {
  if (values.length < 3) return values.slice();
  const out: number[] = [];
  const n = values.length;
  for (let i = 0; i < n - 1; i += 1) {
    const p0 = values[Math.max(0, i - 1)];
    const p1 = values[i];
    const p2 = values[i + 1];
    const p3 = values[Math.min(n - 1, i + 2)];
    for (let s = 0; s < perSegment; s += 1) {
      const t = s / perSegment;
      const t2 = t * t;
      const t3 = t2 * t;
      out.push(
        0.5 *
          (2 * p1 +
            (-p0 + p2) * t +
            (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
            (-p0 + 3 * p1 - 3 * p2 + p3) * t3),
      );
    }
  }
  out.push(values[n - 1]);
  return out;
}

/* dense, smoothed points spanning exactly `spanSecs` — keeps the chart window
 * unchanged while multiplying the resolution. */
function smoothPoints(values: number[], spanSecs: number): LivelinePoint[] {
  const dense = smooth(values);
  return makePoints(dense, spanSecs / (dense.length - 1));
}

function useDarkMode() {
  const [dark, setDark] = useState(false);

  useEffect(() => {
    const root = document.documentElement;
    const update = () => setDark(root.classList.contains("dark"));
    update();
    const observer = new MutationObserver(update);
    observer.observe(root, { attributes: true, attributeFilter: ["class"] });
    return () => observer.disconnect();
  }, []);

  return dark;
}

/* inline @entity mention */
function Entity({ name, tone }: { name: string; tone: string }) {
  return (
    <span className="inline-flex items-center gap-1 align-baseline font-medium text-ink">
      <span className={`inline-block size-2.5 rounded-full ${tone}`} />
      @{name}
    </span>
  );
}

function Mono({ children, tone }: { children: React.ReactNode; tone: "red" | "green" }) {
  return (
    <code className={`font-mono text-[11.5px] ${tone === "red" ? "text-red" : "text-green"}`}>
      {children}
    </code>
  );
}

function chartIndexFromPointer(event: React.PointerEvent<HTMLDivElement>, pointCount: number) {
  const rect = event.currentTarget.getBoundingClientRect();
  const progress = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
  return Math.round(progress * (pointCount - 1));
}

function ChartTooltip({ rows }: { rows: { label: string; value: string; color: string }[] }) {
  return (
    <div className="insight-chart-tooltip">
      {rows.map((row) => (
        <span key={row.label} className="insight-chart-tooltip-item">
          <span className="insight-chart-tooltip-dot" style={{ background: row.color }} />
          {row.value}
        </span>
      ))}
    </div>
  );
}

/* content shape for the return-comparison card's two plotted series */
export type CompareSeries = {
  name: string;
  values: number[];
  sub: string;
  tone: "red" | "green";
  dot: string;
  color: string;
  tooltipColor: string;
};

const COMPARE_SERIES: CompareSeries[] = [
  {
    name: "At risk",
    values: [-2.9, -3.4, -3.05, -3.86, -3.52, -4.1, -3.82, -4.41],
    sub: "-$2,377.66",
    tone: "red",
    dot: "bg-orange",
    color: "#f68f3c",
    tooltipColor: "var(--orange)",
  },
  {
    name: "Healthy",
    values: [0.22, 0.58, 0.42, 0.91, 0.76, 1.08, 0.96, 1.15],
    sub: "+$617.22",
    tone: "green",
    dot: "bg-accent",
    color: "#3d9aff",
    tooltipColor: "var(--accent)",
  },
];

/* 1 — return comparison: 2 series, legend + big deltas + line chart */
function CompareCard({ series = COMPARE_SERIES }: { series?: CompareSeries[] }) {
  const dark = useDarkMode();
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const points = useMemo(
    () => series.map((s) => smoothPoints(s.values, 42)),
    [series],
  );
  const pointCount = points[0]?.length ?? 0;

  const chartSeries: LivelineSeries[] = useMemo(
    () =>
      series.map((s, i) => ({
        id: s.name,
        label: "",
        data: points[i],
        value: points[i].at(-1)?.value ?? (s.values.at(-1) ?? 0),
        color: s.color,
      })),
    [series, points],
  );

  return (
    <div className="min-h-[278px] rounded-card bg-surface p-3 shadow-hairline">
      <div className="flex items-center gap-4">
        {series.map((s, i) => (
          <div key={s.name} className="flex-1">
            <span className="flex items-center gap-1.5 text-[11.5px] text-ink-2">
              <span className={`size-2 rounded-full ${s.dot}`} />
              {s.name}
            </span>
            <span className={`block text-[17px] font-semibold tracking-[-0.01em] tabular-nums ${s.tone === "red" ? "text-red" : "text-green"}`}>
              {formatPercent(points[i].at(-1)?.value ?? (s.values.at(-1) ?? 0))}
            </span>
            <Mono tone={s.tone}>{s.sub}</Mono>
          </div>
        ))}
      </div>
      <div className="mt-2 overflow-hidden rounded-control bg-inset shadow-hairline">
        <div className="flex items-center justify-between border-b border-line px-2.5 py-1.5">
          <span className="text-[11px] text-ink-3 tabular-nums">
            Trend snapshot
          </span>
          <span className="rounded-full bg-field px-2 py-0.5 text-[10.5px] font-medium text-ink-2">
            Snapshot
          </span>
        </div>
        <div
          className="insight-chart-stage relative h-[166px]"
          onPointerDown={(event) => setHoverIndex(chartIndexFromPointer(event, pointCount))}
          onPointerMove={(event) => setHoverIndex(chartIndexFromPointer(event, pointCount))}
          onPointerLeave={() => setHoverIndex(null)}
          onPointerCancel={() => setHoverIndex(null)}
          onPointerUp={() => setHoverIndex(null)}
        >
          <Liveline
            data={[]}
            value={0}
            series={chartSeries}
            theme={dark ? "dark" : "light"}
            grid={false}
            pulse={false}
            window={42}
            paused
            scrub={false}
            cursor="default"
            lineWidth={2.25}
            padding={{ top: 40, right: 0, bottom: 22, left: 0 }}
            formatValue={formatPercent}
          />
          {hoverIndex !== null && <>
            <span className="insight-chart-cursor" style={{ left: `${(hoverIndex / (pointCount - 1)) * 100}%` }} />
            <span className="insight-chart-tooltip-anchor" style={{ left: `${Math.min(Math.max((hoverIndex / (pointCount - 1)) * 100, 28), 72)}%` }}>
              <ChartTooltip rows={series.map((s, i) => ({ label: s.name, value: formatPercent(points[i][hoverIndex].value), color: s.tooltipColor }))} />
            </span>
          </>}
        </div>
      </div>
    </div>
  );
}

/* content shape for the anomaly card's two toggled metric series */
export type AnomalyData = {
  spend: number[];
  usage: number[];
};

const ANOMALY_DATA: AnomalyData = {
  spend: [274, 289, 264, 307, 331, 1210, 1718, 2112],
  usage: [18, 19, 17, 21, 22, 58, 81, 96],
};

/* 2 — anomaly: bars with threshold + big spent value */
function AnomalyCard({ data: anomaly = ANOMALY_DATA }: { data?: AnomalyData }) {
  const dark = useDarkMode();
  const [metric, setMetric] = useState<"spend" | "usage">("spend");
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const spend = useMemo(
    () => makePoints(anomaly.spend, 7),
    [anomaly],
  );
  const usage = useMemo(
    () => makePoints(anomaly.usage, 7),
    [anomaly],
  );

  const data = metric === "spend" ? spend : usage;
  const value = data.at(-1)?.value ?? (metric === "spend" ? 2112 : 96);
  const threshold = metric === "spend" ? "$2,112" : "82 kWh";
  const moneyLabel = formatMoney(spend.at(-1)?.value ?? 2112);

  return (
    <div className="min-h-[278px] rounded-card bg-surface p-3 shadow-hairline">
      <div className="flex items-center justify-between">
        <span className="flex items-center gap-1.5 text-[12px] font-medium text-ink">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="var(--red)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 19V5M5 12l7-7 7 7" /></svg>
          Unusual support activity
        </span>
        <span className="rounded-full bg-field px-2 py-0.5 text-[10.5px] font-medium text-ink-2">
          Snapshot
        </span>
      </div>
      <div className="mt-2 overflow-hidden rounded-control bg-inset shadow-hairline">
        <div className="flex items-center justify-between border-b border-line px-2.5 py-1.5">
          <span className="text-[11px] text-ink-3 tabular-nums">
            {hoverIndex !== null
              ? metric === "spend"
                ? formatMoney(data[hoverIndex].value)
                : `${Math.round(data[hoverIndex].value)} kWh`
              : `${threshold} threshold`}
          </span>
          <span className="flex rounded-full bg-field p-0.5">
            {(["spend", "usage"] as const).map((item) => (
              <button
                key={item}
                type="button"
                aria-pressed={metric === item}
                onClick={() => setMetric(item)}
                className={`rounded-full px-2 py-0.5 text-[10.5px] font-medium transition-[background-color,color,box-shadow,transform] duration-150 active:scale-[0.96] ${
                  metric === item ? "bg-surface text-ink shadow-btn" : "text-ink-3 hover:text-ink-2"
                }`}
              >
                {item === "spend" ? "Spend" : "Usage"}
              </button>
            ))}
          </span>
        </div>
        <div
          className="insight-chart-stage relative h-[166px]"
          onPointerDown={(event) => setHoverIndex(chartIndexFromPointer(event, data.length))}
          onPointerMove={(event) => setHoverIndex(chartIndexFromPointer(event, data.length))}
          onPointerLeave={() => setHoverIndex(null)}
          onPointerCancel={() => setHoverIndex(null)}
          onPointerUp={() => setHoverIndex(null)}
        >
          <Liveline
            data={data}
            value={value}
            theme={dark ? "dark" : "light"}
            color="#ee5c61"
            grid
            scrub={false}
            fill={false}
            pulse={false}
            momentum={false}
            paused
            window={49}
            lineWidth={2.25}
            cursor="crosshair"
            padding={{ top: 34, right: 0, bottom: 22, left: 0 }}
            formatValue={(v) => (metric === "spend" ? formatMoney(v) : `${Math.round(v)} kWh`)}
          />
          {hoverIndex !== null && <>
            <span className="insight-chart-cursor" style={{ left: `${(hoverIndex / (data.length - 1)) * 100}%` }} />
            <span className="insight-chart-tooltip-anchor" style={{ left: `${Math.min(Math.max((hoverIndex / (data.length - 1)) * 100, 28), 72)}%` }}>
              <ChartTooltip rows={[{ label: metric === "spend" ? "Spend" : "Usage", value: metric === "spend" ? formatMoney(data[hoverIndex].value) : `${Math.round(data[hoverIndex].value)} kWh`, color: "var(--red)" }]} />
            </span>
          </>}
        </div>
      </div>
      <div className="mt-1.5 flex items-baseline gap-2">
        <span className="text-[17px] font-semibold tracking-[-0.01em] text-ink tabular-nums">
          {moneyLabel} spent
        </span>
        <Mono tone="red">+$1,834.66</Mono>
        <span className="text-[11px] text-ink-3">vs 3 months</span>
      </div>
    </div>
  );
}

/* content shape for one allocation segment */
export type AllocationSegment = {
  name: string;
  label: string;
  pct: number;
  amount: string;
  cls: string;
  tone: string;
};

const ALLOCATION_SEGMENTS: AllocationSegment[] = [
  { name: "ENT", label: "Enterprise", pct: 72.5, amount: "$51,785", cls: "bg-orange", tone: "text-orange" },
  { name: "MID", label: "Mid-market", pct: 22.8, amount: "$16,278", cls: "bg-line-strong", tone: "text-ink-2" },
  { name: "SMB", label: "Small business", pct: 4.7, amount: "$3,357", cls: "bg-line", tone: "text-ink-3" },
];

/* 3 — allocation: hero number + segmented bar + legend */
function AllocationCard({ segments = ALLOCATION_SEGMENTS }: { segments?: AllocationSegment[] }) {
  const [selected, setSelected] = useState(segments[0].name);
  const active = segments.find((segment) => segment.name === selected) ?? segments[0];

  return (
    <div className="min-h-[278px] rounded-card bg-surface p-3 shadow-hairline">
      <span className="flex items-center gap-1.5 text-[12px] font-medium text-ink">
        <span className="flex size-3.5 items-center justify-center rounded-full bg-orange text-[8px] font-bold text-white">
          V
        </span>
        Renewal allocation
      </span>
      <span className="mt-1 block text-[20px] font-semibold tracking-[-0.01em] text-ink tabular-nums">
        {active.amount}
      </span>
      <div
        className="mt-3 flex h-9 gap-0.5 overflow-hidden rounded-full bg-field p-0.5"
        role="group"
        aria-label="Allocation segments"
      >
        {segments.map((s) => (
          <button
            key={s.name}
            type="button"
            aria-pressed={selected === s.name}
            aria-label={`${s.label}: ${s.pct}%`}
            onClick={() => setSelected(s.name)}
            className={`relative h-full overflow-hidden rounded-full ${s.cls} transition-[opacity,transform,box-shadow] duration-300 active:scale-[0.98]`}
            style={{
              width: `${s.pct}%`,
              opacity: selected === s.name ? 1 : 0.58,
              boxShadow: selected === s.name ? "inset 0 0 0 1px rgba(255,255,255,0.22)" : undefined,
              transitionTimingFunction: EASE,
            }}
          >
            <span
              className="absolute inset-y-1 left-1 rounded-full bg-white/20 transition-[width,opacity] duration-500"
              style={{
                width: selected === s.name ? "calc(100% - 8px)" : "0%",
                opacity: selected === s.name ? 1 : 0,
                transitionTimingFunction: EASE,
              }}
            />
          </button>
        ))}
      </div>
      <div className="mt-2 flex items-center gap-1.5">
        {segments.map((s) => (
          <button
            key={s.name}
            type="button"
            aria-pressed={selected === s.name}
            onClick={() => setSelected(s.name)}
            className={`flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[11px] transition-[background-color,color,transform] duration-150 active:scale-[0.96] ${
              selected === s.name ? "bg-field text-ink" : "text-ink-2 hover:bg-hover hover:text-ink"
            }`}
          >
            <span className={`size-1.5 rounded-full ${s.cls}`} />
            {s.name} <span className="tabular-nums">{s.pct}%</span>
          </button>
        ))}
      </div>
      <div className="mt-3 min-h-16 rounded-control bg-inset px-2.5 py-2 shadow-hairline">
        <span className={`block text-[11.5px] font-medium ${active.tone}`}>{active.label}</span>
        <span className="mt-1 block text-[11px] leading-relaxed text-ink-3">
          Contribution snapshot across current inventory value. Segment selection changes the inspected group without moving the card.
        </span>
      </div>
    </div>
  );
}

/* content shape for one insight page in the carousel */
export type InsightPage = {
  key: string;
  prose: React.ReactNode;
  Card: React.ComponentType;
  pill: string;
};

const PAGES: InsightPage[] = [
  {
    key: "compare",
    prose: (
      <>
        The weakest segment in <Entity name="Renewals" tone="bg-orange" /> is
        mid-market — down <Mono tone="red">-6%</Mono> or <Mono tone="red">-$2,453.44</Mono>.
      </>
    ),
    Card: CompareCard,
    pill: "Which accounts drive the decline?",
  },
  {
    key: "anomaly",
    prose: (
      <>
        Unusually high support activity on <span className="font-medium text-ink">Dec 13</span> —{" "}
        <Mono tone="red">+$1,834.66</Mono> above your average.
      </>
    ),
    Card: AnomalyCard,
    pill: "Show the affected accounts",
  },
  {
    key: "allocation",
    prose: (
      <>
        Enterprise accounts represent <Entity name="Renewal value" tone="bg-orange" /> — they are{" "}
        <span className="font-medium text-ink">72.5%</span> of your case.
      </>
    ),
    Card: AllocationCard,
    pill: "How does this compare by segment?",
  },
];

export type InsightCardsLabels = {
  /** carousel heading shown before the page count */
  title: string;
};

const DEFAULT_INSIGHT_LABELS: InsightCardsLabels = {
  title: "Insights",
};

export default function InsightCards({
  pages = PAGES,
  labels,
}: {
  variant?: string;
  pages?: InsightPage[];
  labels?: Partial<InsightCardsLabels>;
} = {}) {
  const l = { ...DEFAULT_INSIGHT_LABELS, ...labels };
  const [page, setPage] = useState(0);

  const move = (direction: -1 | 1) => {
    setPage((current) => (current + direction + pages.length) % pages.length);
  };

  const { prose, Card, pill } = pages[page];

  return (
    <div className="min-h-[408px] w-full max-w-86">
      {/* pager header */}
      <div className="flex items-center justify-between">
        <span className="flex items-baseline gap-1.5">
          <span className="text-[13px] font-semibold text-ink">{l.title}</span>
          <span className="text-[13px] text-ink-3 tabular-nums">{pages.length}</span>
        </span>
        <span className="flex items-center gap-0.5">
          {(["M15 18l-6-6 6-6", "M9 6l6 6-6 6"] as const).map((d, i) => (
            <button
              key={i}
              aria-label={i === 0 ? "Previous insight" : "Next insight"}
              onClick={() => move(i === 0 ? -1 : 1)}
              className="flex size-6 items-center justify-center rounded-[6px] text-ink-3
                transition-[background-color,color,transform] duration-100 hover:bg-hover
                hover:text-ink active:scale-[0.96]"
            >
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                <path d={d} />
              </svg>
            </button>
          ))}
        </span>
      </div>

      {/* page content — blurred crossfade */}
      <div
        className="transition-[opacity,filter] duration-250"
        style={{ opacity: 1, filter: "blur(0)" }}
      >
        <p className="mt-1.5 text-[12.5px] leading-relaxed text-ink-2">{prose}</p>
        <div className="mt-2">
          <Card />
        </div>
        <button
          className="mt-2 rounded-full bg-surface px-3 py-1.5 text-left text-[12px] text-ink
            shadow-btn transition-colors duration-100 hover:bg-hover"
        >
          {pill}
        </button>
      </div>
    </div>
  );
}

/* GENERIC FOUNDATION — tokens, @theme, base rules, the primitive-*
 * spacing utilities, and shared keyframes below are needed by EVERY
 * component. Blocks tagged COMPONENT-SPECIFIC further down belong to
 * one primitive each. */
/* ──────────────────────────────────────────────────────────
 * Beautiful UI — design tokens
 * Cool near-white canvas, white cards, hairline borders, layered
 * single-digit-opacity shadows, a neutral ink ramp, and semantic
 * color used sparingly as a condiment.
 * ────────────────────────────────────────────────────────── */

.beautiful-ui-scope {
  /* surfaces — cool, blue-tinted neutrals */
  --page: oklch(0.985 0.001 286.376);
  --canvas: oklch(0.961 0.002 247.84);
  --surface: oklch(1 0 0);
  --inset: oklch(0.979 0.002 247.839);
  --hover: oklch(0.97 0.002 247.839);
  --hover-2: oklch(0.933 0.003 247.86);

  /* ink ramp */
  --ink: oklch(0.247 0.006 258.361);
  --ink-2: oklch(0.506 0.01 264.477);
  --ink-3: oklch(0.695 0.009 264.505);

  /* borders — solid and crisp, not alpha */
  --line: oklch(0.946 0.003 264.542);
  --line-strong: oklch(0.912 0.005 258.326);
  --line-soft: oklch(0.966 0.002 264.542);
  --grid-line: color-mix(in srgb, var(--line) 78%, transparent);
  --field: oklch(0.961 0.001 286.375);
  --stripe: oklch(0.405 0 0 / 0.075);
  --stripe-bg: oklch(0.97 0 0);

  /* accent */
  --accent: oklch(0.626 0.205 254.947);
  --accent-ink: oklch(0.556 0.187 255.617);
  --accent-tint: oklch(0.96 0.019 252.878);

  /* semantic */
  --green: oklch(0.603 0.155 150.883);
  --green-tint: oklch(0.958 0.017 159.118);
  --orange: oklch(0.689 0.179 49.902);
  --orange-tint: oklch(0.964 0.021 67.581);
  --red: oklch(0.621 0.192 23.042);
  --red-tint: oklch(0.956 0.017 17.462);

  /* chart overlays — neutral system colors with enough contrast on either theme */
  --tooltip-bg: oklch(0.272 0.008 264.435);
  --tooltip-fg: oklch(0.976 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.356 0.007 264.474);

  /* shadows — our solid hairline ring + shadow-plugin's smooth layered stacks
   * (--shadow-xs…lg come from shadow-plugin/unprefixed) so every surface reads
   * consistently across the app. */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-xs: 0 0 4px 0 rgba(0, 0, 0, 0.04);
  --shadow-sm: 0 18px 47px 0 rgba(0, 0, 0, 0.03), 0 7.5px 19px 0 rgba(0, 0, 0, 0.02), 0 4px 10.5px 0 rgba(0, 0, 0, 0.02), 0 2.3px 5.8px 0 rgba(0, 0, 0, 0.01), 0 1.2px 3.1px 0 rgba(0, 0, 0, 0.01), 0 0.5px 1.3px 0 rgba(0, 0, 0, 0.01);
  --shadow-md: 0 17.54px 23.39px 0 rgba(0, 0, 0, 0.04), 0 9.4px 12.5px 0 rgba(0, 0, 0, 0.03), 0 5.25px 7px 0 rgba(0, 0, 0, 0.02), 0 2.79px 3.72px -2px rgba(0, 0, 0, 0.01), 0 1.16px 1.5px 0 rgba(0, 0, 0, 0.01);
  --shadow-lg: 0 25px 50px 0 rgba(0, 0, 0, 0.05), 0 12px 24px 0 rgba(0, 0, 0, 0.04), 0 6px 12px 0 rgba(0, 0, 0, 0.03), 0 3px 6px 0 rgba(0, 0, 0, 0.02), 0 1.5px 3px 0 rgba(0, 0, 0, 0.02);
  --shadow-btn: 0 0 0 1px var(--line-strong), var(--shadow-xs);
  --shadow-card: 0 0 0 1px var(--line), var(--shadow-sm);
  --shadow-raised: 0 0 0 1px var(--line), var(--shadow-md);
  --shadow-overlay: 0 0 0 1px var(--line), var(--shadow-lg);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.12);
}

.beautiful-ui-scope :is(button:not(:disabled), [role="button"]:not([aria-disabled="true"]), label:has(input), a) {
  cursor: pointer;
}

.beautiful-ui-scope :focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.beautiful-ui-scope :is(input, textarea, select, [contenteditable]):focus-visible {
  outline: none;
}

.dark .beautiful-ui-scope {
  --page: oklch(0.209 0.004 264.477);
  --canvas: oklch(0.231 0.004 264.487);
  --surface: oklch(0.26 0.006 271.191);
  --inset: oklch(0.243 0.004 264.492);
  --hover: oklch(0.289 0.006 271.22);
  --hover-2: oklch(0.318 0.007 274.747);

  --ink: oklch(0.964 0.002 247.839);
  --ink-2: oklch(0.731 0.008 260.731);
  --ink-3: oklch(0.541 0.01 264.484);

  --line: oklch(0.308 0.006 258.354);
  --line-strong: oklch(0.356 0.007 264.474);
  --line-soft: oklch(0.278 0.006 258.354);
  --field: oklch(0.293 0.006 271.223);
  --stripe: oklch(1 0 0 / 0.055);
  --stripe-bg: oklch(0.226 0.004 264.485);

  --accent: oklch(0.68 0.173 253.301);
  --accent-ink: oklch(0.788 0.113 248.33);
  --accent-tint: oklch(0.68 0.173 253.301 / 0.16);

  --green: oklch(0.705 0.154 153.814);
  --green-tint: oklch(0.705 0.154 153.814 / 0.14);
  --orange: oklch(0.746 0.156 55.642);
  --orange-tint: oklch(0.746 0.156 55.642 / 0.14);
  --red: oklch(0.666 0.18 21.433);
  --red-tint: oklch(0.666 0.18 21.433 / 0.14);

  --tooltip-bg: oklch(0.182 0.004 264.459);
  --tooltip-fg: oklch(0.964 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.308 0.006 258.354);

  --shadow-hairline: 0 0 0 1px var(--line);
  /* Elevation rings go to a subtle *light* hairline in dark mode: the ring
   * paints over the surface behind the element, so a low-alpha white edge
   * dissolves into the shadow as one continuous stroke (per smooth-shadow-ring),
   * graduated by how far the surface floats. */
  --shadow-btn: 0 0 0 1px oklch(1 0 0 / 0.1), 0 1px 2px oklch(0 0 0 / 0.3);
  --shadow-card:
    0 0 0 1px oklch(1 0 0 / 0.11), 0 1px 2px oklch(0 0 0 / 0.2),
    0 2px 6px oklch(0 0 0 / 0.2);
  --shadow-raised:
    0 0 0 1px oklch(1 0 0 / 0.13), 0 2px 10px oklch(0 0 0 / 0.22);
  --shadow-overlay:
    0 0 0 1px oklch(1 0 0 / 0.15), 0 8px 28px oklch(0 0 0 / 0.34);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.4);
}

@theme inline {
  /* colors */
  --color-page: var(--page);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-inset: var(--inset);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-hover: var(--hover);
  --color-hover-2: var(--hover-2);
  --color-field: var(--field);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-tint: var(--accent-tint);
  --color-green: var(--green);
  --color-green-tint: var(--green-tint);
  --color-orange: var(--orange);
  --color-orange-tint: var(--orange-tint);
  --color-red: var(--red);
  --color-red-tint: var(--red-tint);

  /* shadows */
  --shadow-hairline: var(--shadow-hairline);
  --shadow-btn: var(--shadow-btn);
  --shadow-inset-field: var(--shadow-inset-field);
  --shadow-card: var(--shadow-card);
  --shadow-raised: var(--shadow-raised);
  --shadow-overlay: var(--shadow-overlay);

  /* type */
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-mono-face), ui-monospace, "SF Mono", monospace;

  /* radii — chips 6, controls 8, cards 10, windows 14, pills 999 */
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-card: 10px;
  --radius-window: 14px;

  /* easing — strong curves; built-ins are too weak */
  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out-strong: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamingText / ContextCards
 * Favicon source avatars.
 * Copy this block only alongside StreamingText / ContextCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.source-avatar {
  box-shadow: 0 0 0 1px oklch(0.21 0.034 263.436 / 0.1);
}

.dark .beautiful-ui-scope .source-avatar {
  box-shadow: 0 0 0 1px oklch(1 0 0 / 0.08);
}

/* ── primitive spacing system ─────────────────────────────
 * Shared optical offsets for small demo cards. Use these
 * instead of hand-tuning 10/12/14px per component.
 */

.primitive-card-pad {
  padding: 12px;
}

.primitive-card-bar {
  padding: 10px 12px;
}

.primitive-card-footer {
  padding: 10px;
}

.primitive-table-cell {
  padding: 10px 12px;
}

.primitive-icon-button {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-control);
}

/* ── shared keyframes ─────────────────────────────────── */

@keyframes beautiful-shimmer-text {
  from {
    background-position: 150% center;
  }
  to {
    background-position: -50% center;
  }
}

@keyframes beautiful-fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.home-reveal {
  will-change: opacity, transform, filter;
}

/* The sidebar is one persistent 224px tree clipped by a 52px shell.
 * Every rail glyph remains centered at x=26 in both states. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — SidebarNav
 * The 52↔224px collapsible sidebar tree.
 * Copy this block only alongside SidebarNav; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.sidebar-row {
  width: 208px;
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: var(--sidebar-easing);
}

.sidebar-copy {
  opacity: 1;
  transform: translateX(0);
  transition:
    opacity var(--sidebar-copy-duration) ease-out,
    transform var(--sidebar-copy-duration) var(--sidebar-easing);
}

.sidebar-logo,
.sidebar-collapse-control,
.sidebar-expand-control {
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: ease-out;
}

.sidebar-expand-control {
  pointer-events: none;
  opacity: 0;
}

.sidebar-glide-highlight {
  right: 8px;
  left: 8px;
}

[data-sidebar-collapsed="true"] .sidebar-row {
  width: 36px;
}

[data-sidebar-collapsed="true"] .sidebar-copy {
  pointer-events: none;
  opacity: 0;
  transform: translateX(calc(var(--sidebar-copy-offset) * -1));
}

[data-sidebar-collapsed="true"] .sidebar-workspace-control {
  pointer-events: none;
}

[data-sidebar-collapsed="true"] .sidebar-logo,
[data-sidebar-collapsed="true"] .sidebar-collapse-control {
  pointer-events: none;
  opacity: 0;
}

[data-sidebar-collapsed="true"] .sidebar-expand-control {
  pointer-events: auto;
  opacity: 1;
}

[data-sidebar-collapsed="true"] .sidebar-glide-highlight {
  right: auto;
  width: 36px;
}

@media (prefers-reduced-motion: reduce) {
  .home-reveal {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
  }
}

/* ── records table ────────────────────────────────────────
 * The grid is deliberately more architectural than card-like:
 * one quiet surface, precise rules, and color reserved for
 * meaning. The first column remains an anchor while both axes
 * can move independently inside the table viewport.
 */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — RecordsTable
 * The full CRM grid, spreadsheet gutter, and AI column (~800 lines).
 * Copy this block only alongside RecordsTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.records-shell {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  box-shadow: 0 1px 2px oklch(0 0 0 / 0.06);
}

/* fill mode: the shell stretches to fill its container and drops its own
 * border/radius/shadow so it reads as part of the surrounding card rather
 * than a container-in-a-container. The grid body flexes to fill height. */
.records-shell.is-fill {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  height: 100%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.records-shell.is-fill .records-scroll {
  max-height: none;
  flex: 1;
}

.records-toolbar {
  display: flex;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--surface);
}

.records-toolbar-left,
.records-toolbar-right,
.records-company-header,
.records-quiet-button,
.records-secondary-button,
.records-primary-button,
.records-select-button,
.records-strength,
.records-link,
.records-add-calculation {
  display: inline-flex;
  align-items: center;
}

.records-toolbar-left,
.records-toolbar-right {
  gap: 4px;
}

.records-toolbar-right {
  flex-shrink: 0;
}

.records-select-button,
.records-quiet-button,
.records-secondary-button,
.records-primary-button {
  height: 32px;
  gap: 7px;
  border-radius: var(--radius-control);
  padding: 0 10px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms var(--ease-out-strong), color 140ms var(--ease-out-strong), transform 140ms var(--ease-out-strong), box-shadow 140ms var(--ease-out-strong);
}

.records-select-button {
  gap: 8px;
  color: var(--ink);
  border: 1px solid var(--line);
  background: var(--surface);
}

.records-select-button:hover,
.records-quiet-button:hover,
.records-secondary-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-quiet-button {
  color: var(--ink-2);
}

.records-quiet-button.is-active {
  background: var(--accent-tint);
  color: var(--accent-ink);
}

.records-secondary-button {
  border: 1px solid var(--tooltip-border);
  color: var(--ink-2);
  box-shadow: none;
}

.records-primary-button {
  margin-left: 3px;
  background: var(--accent);
  color: oklch(1 0 0);
  box-shadow: none;
}

.records-primary-button:hover {
  filter: saturate(0.9) brightness(1.04);
}

.records-quiet-button:active,
.records-secondary-button:active,
.records-primary-button:active,
.records-select-button:active,
.records-add-calculation:active {
  transform: scale(0.96);
}

.records-database-icon {
  display: inline-flex;
  color: var(--green);
}

.records-filter-wrap {
  position: relative;
}

.records-filter-dot {
  width: 5px;
  height: 5px;
  margin-left: -2px;
  border-radius: 99px;
  background: var(--accent);
}

.records-filter-menu {
  position: absolute;
  z-index: 30;
  top: calc(100% + 7px);
  left: 0;
  width: 190px;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-card);
  background: var(--surface);
  box-shadow: var(--shadow-overlay);
  animation: beautiful-pop-in 160ms var(--ease-out-strong) both;
  transform-origin: top left;
}

.records-sort-menu {
  left: -48px;
}

.records-filter-label {
  padding: 5px 8px 6px;
  color: var(--ink-3);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.records-filter-menu button {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 7px;
  border-radius: var(--radius-chip);
  padding: 7px 8px;
  color: var(--ink-2);
  font-size: 12px;
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-filter-menu button:hover,
.records-filter-menu button.is-selected {
  background: var(--hover);
  color: var(--ink);
}

.records-menu-check {
  width: 13px;
  color: var(--accent-ink);
  font-size: 12px;
  font-weight: 500;
  text-align: center;
}

.records-scroll {
  max-height: 438px;
  overflow: auto;
  overscroll-behavior: none;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-gutter: stable;
}

.records-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.records-table {
  width: 100%;
  min-width: 990px;
  border-collapse: separate;
  border-spacing: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  table-layout: fixed;
}

.records-company-col { width: 270px; }
.records-category-col { width: 275px; }
.records-last-col { width: 190px; }
.records-strength-col { width: 210px; }
.records-link-col { width: 175px; }

.records-table th,
.records-table td {
  border-right: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  text-align: left;
  vertical-align: middle;
}

.records-table tr > :last-child {
  border-right: 0;
}

.records-table thead th {
  position: sticky;
  z-index: 5;
  top: 0;
  height: 35px;
  background: var(--surface);
  color: var(--ink-2);
  font-size: 12.5px;
  font-weight: 500;
}

.records-header-cell {
  padding: 0;
}

.records-resize-handle {
  position: absolute;
  z-index: 12;
  top: 0;
  right: -6px;
  width: 12px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}

.records-resize-handle::after {
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 5px;
  width: 2px;
  border-radius: 99px;
  background: var(--accent);
  content: "";
  opacity: 0;
  transform: scaleY(0.65);
  transition: opacity 120ms ease-out, transform 150ms var(--ease-out-strong);
}

.records-resize-handle:hover::after,
.records-resize-handle.is-resizing::after {
  opacity: 1;
  transform: scaleY(1);
}

.records-header-cell.records-sticky-cell {
  z-index: 7;
}

.records-header-button,
.records-company-header {
  width: 100%;
  height: 35px;
  gap: 8px;
  padding: 0 12px;
}

.records-company-header {
  padding-left: 6px;
}

.records-header-button {
  display: flex;
  align-items: center;
  color: var(--ink-2);
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-header-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-header-icon {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--ink-3);
}

.records-sort {
  display: inline-flex;
  flex-shrink: 0;
  margin-left: auto;
  opacity: 0;
  transition: opacity 120ms ease-out, transform 160ms var(--ease-out-strong);
}

.records-header-button:hover .records-sort,
.records-sort.is-visible {
  opacity: 1;
}

.records-company-header {
  display: flex;
}

.records-company-header > span:not(.records-checkbox-box) {
  white-space: nowrap;
}

.records-add-field {
  display: inline-flex;
  margin-left: auto;
  color: var(--ink-3);
  opacity: 0;
  transition: opacity 120ms ease-out, color 120ms ease-out;
}

.records-company-header:hover .records-add-field,
.records-add-field:focus-visible {
  opacity: 1;
}

.records-add-field:hover {
  color: var(--ink);
}

.records-checkbox {
  position: relative;
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-chip);
}

.records-checkbox input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.records-checkbox-box {
  display: inline-flex;
  width: 18px;
  height: 18px;
  align-items: center;
  justify-content: center;
  border: 1px solid oklch(0.845 0.011 247.953);
  border-radius: 6px;
  color: oklch(0.446 0.018 251.343);
  background: oklch(1 0 0);
  transition: border-color 140ms ease-out, background-color 140ms ease-out, box-shadow 140ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.773 0.016 251.194);
  background: oklch(0.966 0.003 228.784);
}

.records-checkbox:active .records-checkbox-box {
  transform: scale(0.96);
}

.records-checkbox input:focus-visible + .records-checkbox-box {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
  box-shadow: none;
}

.records-checkbox-dash {
  width: 8px;
  height: 1.5px;
  border-radius: 99px;
  background: oklch(1 0 0);
}

.dark .beautiful-ui-scope .records-checkbox-box {
  border-color: oklch(0.45 0.017 254.711);
  color: oklch(0.917 0.007 247.901);
  background: oklch(0.346 0.015 252.294);
}

.dark .beautiful-ui-scope .records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.521 0.019 254);
  background: oklch(0.391 0.016 251.761);
}

.dark .beautiful-ui-scope .records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
}

.dark .beautiful-ui-scope .records-checkbox-dash {
  background: oklch(1 0 0);
}

.records-cell {
  height: 35px;
  padding: 0 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.records-sticky-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--surface);
  box-shadow: 5px 0 8px -10px oklch(0 0 0 / 0.4);
}

.records-company-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 6px;
  overflow: visible;
}

.records-row > .records-cell {
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-row:hover > .records-cell {
  background: var(--hover);
}

.records-row.is-selected > .records-cell {
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

/* ── spreadsheet gutter ──────────────────────────────────
 * Row numbers at rest; the checkbox takes their place on
 * hover or once the row is selected. */
.records-rownum {
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  color: var(--ink-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.records-row .records-checkbox {
  display: none;
}

.records-row:hover .records-rownum,
.records-row.is-selected .records-rownum {
  display: none;
}

.records-row:hover .records-checkbox,
.records-row.is-selected .records-checkbox {
  display: inline-flex;
}

/* ── selected column — the property being configured ───── */
.records-table th.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  box-shadow: inset 0 2px 0 var(--accent);
}

th.is-colsel .records-header-button,
th.is-colsel .records-company-header,
th.is-colsel .records-header-icon {
  color: var(--accent-ink);
}

.records-table td.is-colsel {
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}

.records-row:hover > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.records-row.is-selected > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
}

/* ── AI column calculating state ─────────────────────────── */
.records-calc {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.beautiful-records-pulse {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: beautiful-records-pulse 1.1s ease-in-out infinite;
}

@keyframes beautiful-records-pulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

/* agent-screen — a static decorative cursor sitting on the capture (for show) */
.agent-cursor {
  position: absolute;
  pointer-events: none;
  filter: drop-shadow(0 1px 1.5px rgba(0, 0, 0, 0.35));
}

.records-company-mark {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  color: var(--ink-2);
  background: var(--field);
  font-size: 10px;
  font-weight: 500;
}

.records-company-name {
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-company-name.has-link:hover,
.records-company-name.has-link:focus-visible {
  color: var(--accent-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.records-tags {
  position: relative;
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: 4px;
  overflow: hidden;
}

.records-tags-measure {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  width: max-content;
  gap: 4px;
  pointer-events: none;
  visibility: hidden;
}

.records-tags-measure > span {
  display: inline-flex;
}

.records-tag {
  display: inline-flex;
  height: 23px;
  max-width: 115px;
  align-items: center;
  flex-shrink: 0;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--tag-base) 32%, var(--surface));
  border-radius: 8px;
  padding: 0 7px;
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 18%, var(--surface));
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-more-tag {
  display: inline-flex;
  height: 23px;
  align-items: center;
  flex-shrink: 0;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  padding: 0 7px;
  color: var(--ink-3);
  background: var(--inset);
  font-size: 11px;
  font-weight: 500;
}

.records-more-tag {
  border-color: var(--line-strong);
  color: var(--ink-3);
  background: var(--inset);
}

.records-muted {
  color: var(--ink-3);
}

.records-strength {
  gap: 8px;
  color: var(--ink-2);
}

.records-strength-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

.records-link {
  max-width: 100%;
  gap: 5px;
  overflow: hidden;
  color: var(--accent-ink);
  text-overflow: ellipsis;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
  text-underline-offset: 3px;
  transition: color 120ms ease-out, text-decoration-color 120ms ease-out;
}

.records-link-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-link svg {
  flex-shrink: 0;
}

.records-link:hover,
.records-link:focus-visible {
  color: var(--ink);
  text-decoration-color: currentColor;
}

.records-table tfoot td {
  position: sticky;
  z-index: 4;
  bottom: 0;
  height: 35px;
  background: var(--inset);
  color: var(--ink-2);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
}

.records-table tfoot .records-sticky-cell {
  z-index: 6;
  background: var(--inset);
}

.records-calculation-label {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-value {
  display: inline-flex;
  height: 35px;
  align-items: center;
  vertical-align: middle;
}

.records-calculation-number {
  margin-right: 3px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.records-add-calculation {
  height: 35px;
  gap: 6px;
  color: var(--ink-3);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  transition: color 120ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-add-calculation:hover {
  color: var(--ink);
}

.records-average {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-2);
}

.records-calculation-row-secondary td {
  position: sticky;
  bottom: 35px;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-calculation-row-secondary .records-sticky-cell {
  position: sticky;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-footer {
  display: flex;
  min-height: 35px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 12px;
  color: var(--ink-3);
  font-size: 11.5px;
}

.records-footer strong {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-hint {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  opacity: 0;
  transition: opacity 160ms ease-out;
}

.records-shell:hover .records-footer-hint {
  opacity: 1;
}

.records-scroll-cue {
  display: inline-flex;
  color: var(--ink-3);
}

@media (max-width: 640px) {
  .records-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .records-toolbar-left,
  .records-toolbar-right {
    width: 100%;
  }

  .records-toolbar-right {
    justify-content: flex-end;
  }

  .records-footer-hint {
    display: none;
  }
}

/* ── filter table electric status colors ─────────────────── */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — FilterTable
 * Electric status-pill colors.
 * Copy this block only alongside FilterTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  border: 1px solid transparent;
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — InsightCards
 * Liveline chart tooltip + cursor.
 * Copy this block only alongside InsightCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.insight-chart-stage {
  overflow: hidden;
}

.insight-chart-cursor {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--ink);
  opacity: 0.26;
  pointer-events: none;
}

.insight-chart-tooltip-anchor {
  position: absolute;
  z-index: 5;
  top: 8px;
  transform: translateX(-50%);
  pointer-events: none;
}

.insight-chart-tooltip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 9px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--tooltip-fg);
  background: var(--tooltip-bg);
  box-shadow: var(--shadow-overlay);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.insight-chart-tooltip-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.insight-chart-tooltip-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

/* Status pills share the same base-hue → color-mix derivation as .records-tag,
 * so both components stay consistent across light and dark. */
.filter-status-todo {
  --tag-base: oklch(0.757 0.153 66.401);
}
.filter-status-progress {
  --tag-base: oklch(0.671 0.118 219.351);
}
.filter-status-done {
  --tag-base: oklch(0.652 0.131 162.865);
}

.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 20%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

/* Dark mode — a richer, saturated same-hue fill
 * with bright same-hue text and no visible border (light mode keeps the soft
 * tinted pastels above). Applies to both the records grid and status pills. */
.dark .beautiful-ui-scope .records-tag,
.dark .beautiful-ui-scope .filter-status-todo,
.dark .beautiful-ui-scope .filter-status-progress,
.dark .beautiful-ui-scope .filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 86%, white);
  background: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

@keyframes beautiful-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes beautiful-eq-bounce {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

/* ── StreamText primitive ─────────────────────────────────
 * Fast character reveal: the newest few characters carry a
 * soft, masked blur so the leading edge resolves smoothly as
 * text flows in. The caret holds solid while streaming, then
 * blinks once the string settles. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamText
 * The streaming caret + tail.
 * Copy this block only alongside StreamText; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.stream-tail {
  filter: blur(1.6px);
  -webkit-mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
  mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
}

.stream-caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 1.5px;
  translate: 0 -0.5px;
  border-radius: 1px;
  background: var(--ink);
  vertical-align: text-bottom;
  animation: beautiful-caret-blink 1s step-end infinite;
}

.stream-caret.is-streaming {
  animation: none;
}

@keyframes beautiful-caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stream-caret {
    animation: none;
  }
  .stream-tail {
    filter: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

@keyframes beautiful-pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes beautiful-spin {
  to {
    transform: rotate(360deg);
  }
}

/* pixel-grid loader — brighten plateau, staggered per cell */
@keyframes beautiful-pixel-on {
  0%, 100% {
    opacity: 0.15;
  }
  18%, 42% {
    opacity: 1;
  }
  62% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui-scope *,
  .beautiful-ui-scope *::before,
  .beautiful-ui-scope *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
